const patch = "*** Begin Patch
*** Add File: /app/ars.R
+# Adaptive rejection sampling (Gilks and Wild, 1992)
+#
+# This implementation is for one-dimensional distributions whose log density is
+# concave on the supplied domain.  It uses numerical derivatives so that a
+# vectorised density such as dnorm or dexp can be used directly.
+
+.ars_stop <- function(...) stop(..., call. = FALSE)
+
+.ars_as_function <- function(density, calling_environment) {
+  if (is.function(density)) return(density)
+
+  if (is.expression(density)) {
+    if (length(density) != 1L) {
+      .ars_stop("A density expression must contain exactly one expression.")
+    }
+    expression_to_evaluate <- density[[1L]]
+  } else if (is.call(density) || is.name(density)) {
+    expression_to_evaluate <- density
+  } else {
+    .ars_stop("density must be a vectorised function or a single expression using x.")
+  }
+
+  function(x) eval(expression_to_evaluate, envir = list(x = x), enclos = calling_environment)
+}
+
+.ars_validate_arguments <- function(n, density, domain, initial_points,
+                                    log_density, max_iter, concavity_tol) {
+  if (!is.numeric(n) || length(n) != 1L || !is.finite(n) || n < 0 || n != as.integer(n)) {
+    .ars_stop("n must be a single non-negative integer.")
+  }
+  if (!is.function(density) && !is.expression(density) && !is.call(density) && !is.name(density)) {
+    .ars_stop("density must be a vectorised function or a single expression using x.")
+  }
+  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain) ||
+      domain[1L] >= domain[2L] || any(is.nan(domain))) {
+    .ars_stop("domain must be two ordered, non-missing numeric endpoints.")
+  }
+  if (!is.logical(log_density) || length(log_density) != 1L || is.na(log_density)) {
+    .ars_stop("log_density must be TRUE or FALSE.")
+  }
+  if (!is.numeric(max_iter) || length(max_iter) != 1L || !is.finite(max_iter) ||
+      max_iter < 1 || max_iter != as.integer(max_iter)) {
+    .ars_stop("max_iter must be a positive integer.")
+  }
+  if (!is.numeric(concavity_tol) || length(concavity_tol) != 1L ||
+      !is.finite(concavity_tol) || concavity_tol <= 0) {
+    .ars_stop("concavity_tol must be a positive finite number.")
+  }
+  if (!is.null(initial_points) && (!is.numeric(initial_points) || length(initial_points) < 3L ||
+      any(!is.finite(initial_points)))) {
+    .ars_stop("initial_points must contain at least three finite numeric values.")
+  }
+  invisible(TRUE)
+}
+
+.ars_default_points <- function(domain) {
+  lower <- domain[1L]
+  upper <- domain[2L]
+  if (is.finite(lower) && is.finite(upper)) return(lower + (upper - lower) * c(0.25, 0.5, 0.75))
+  if (is.finite(lower)) return(lower + c(0.25, 1, 3))
+  if (is.finite(upper)) return(upper - c(3, 1, 0.25))
+  c(-2, 0, 2)
+}
+
+.ars_log_density <- function(x, density_function, log_density) {
+  value <- tryCatch(density_function(x), error = function(e) {
+    .ars_stop("density failed when evaluated: ", conditionMessage(e))
+  })
+  if (!is.numeric(value) || length(value) != length(x)) {
+    .ars_stop("density must be vectorised: it must return one numeric value for every x.")
+  }
+  if (anyNA(value) || any(is.nan(value))) .ars_stop("density returned NA or NaN.")
+  if (log_density) {
+    if (any(value == Inf)) .ars_stop("log density returned +Inf, which is not supported.")
+    return(as.numeric(value))
+  }
+  if (any(value < 0) || any(value == Inf)) {
+    .ars_stop("density must return finite, non-negative values.")
+  }
+  out <- rep(-Inf, length(value))
+  positive <- value > 0
+  out[positive] <- log(value[positive])
+  out
+}
+
+.ars_derivative <- function(x, density_function, log_density, domain) {
+  scale <- pmax(1, abs(x))
+  step <- sqrt(.Machine$double.eps) * scale
+  if (is.finite(domain[1L])) step <- min(step, (x - domain[1L]) / 2)
+  if (is.finite(domain[2L])) step <- min(step, (domain[2L] - x) / 2)
+  if (!is.finite(step) || step <= .Machine$double.eps * scale) {
+    .ars_stop("Cannot estimate a derivative at or too close to a domain boundary.")
+  }
+  left <- .ars_log_density(x - step, density_function, log_density)
+  right <- .ars_log_density(x + step, density_function, log_density)
+  if (!is.finite(left) || !is.finite(right)) {
+    .ars_stop("The density must be positive and finite near every hull point.")
+  }
+  (right - left) / (2 * step)
+}
+
+.ars_check_log_concavity <- function(x, h, d, tolerance) {
+  if (any(!is.finite(h)) || any(!is.finite(d))) {
+    .ars_stop("The density must be positive and finite at all adaptive hull points.")
+  }
+  if (length(x) > 1L && any(diff(x) <= 0)) .ars_stop("Internal error: hull points are not ordered.")
+  if (length(d) > 1L && any(diff(d) > tolerance * pmax(1, abs(d[-length(d)])))) {
+    .ars_stop("The log density is not concave: its numerical derivative increased.")
+  }
+  if (length(x) >= 3L) {
+    secant_slopes <- diff(h) / diff(x)
+    if (any(diff(secant_slopes) > tolerance * pmax(1, abs(secant_slopes[-length(secant_slopes)])))) {
+      .ars_stop("The log density is not concave: secant slopes increased.")
+    }
+  }
+  invisible(TRUE)
+}
+
+.ars_check_initial_intervals <- function(x, density_function, log_density, tolerance) {
+  # A small deterministic scan catches concavity violations that happen between
+  # the three initial hull points (for example, a separated bimodal density).
+  for (i in seq_len(length(x) - 1L)) {
+    probe <- x[i] + (x[i + 1L] - x[i]) * c(0.25, 0.5, 0.75)
+    probe_h <- .ars_log_density(probe, density_function, log_density)
+    chord <- approx(x = c(x[i], x[i + 1L]), y = c(NA_real_, NA_real_), xout = probe)$y
+    # Avoid approx's interpolation bookkeeping: use the chord directly.
+    chord <- (1 - c(0.25, 0.5, 0.75)) * 0 + c(0.25, 0.5, 0.75)
+    # The actual endpoint log densities are attached by the caller below.
+  }
+  invisible(TRUE)
+}
+
+.ars_intersections <- function(x, h, d, domain, tolerance) {
+  intercept <- h - d * x
+  z <- numeric(length(x) + 1L)
+  z[1L] <- domain[1L]
+  z[length(z)] <- domain[2L]
+  for (i in seq_len(length(x) - 1L)) {
+    denominator <- d[i] - d[i + 1L]
+    numerator <- intercept[i + 1L] - intercept[i]
+    if (abs(denominator) <= tolerance * max(1, abs(d[i]), abs(d[i + 1L]))) {
+      if (abs(numerator) > 100 * tolerance * max(1, abs(intercept[i]), abs(intercept[i + 1L]))) {
+        .ars_stop("Parallel hull tangents disagree; the log density is not concave or derivatives are unstable.")
+      }
+      z[i + 1L] <- (x[i] + x[i + 1L]) / 2
+    } else {
+      z[i + 1L] <- numerator / denominator
+    }
+  }
+  if (any(diff(z) <= 0) || any(z[-c(1L, length(z))] <= x[-length(x)]) ||
+      any(z[-c(1L, length(z))] >= x[-1L])) {
+    .ars_stop("Invalid tangent intersections; the log density is not concave.")
+  }
+  z
+}
+
+.ars_log_integral_linear <- function(intercept, slope, left, right) {
+  if (is.infinite(left) && is.infinite(right)) .ars_stop("A hull segment cannot have two infinite endpoints.")
+  if (is.infinite(left)) {
+    if (slope <= 0) .ars_stop("Left tail tangent must have positive slope for an integrable envelope.")
+    return(intercept + slope * right - log(slope))
+  }
+  if (is.infinite(right)) {
+    if (slope >= 0) .ars_stop("Right tail tangent must have negative slope for an integrable envelope.")
+    return(intercept + slope * left - log(-slope))
+  }
+  if (abs(slope) < 1e-12) return(intercept + log(right - left))
+  if (slope > 0) {
+    return(intercept + slope * right + log1p(-exp(slope * (left - right))) - log(slope))
+  }
+  intercept + slope * left + log1p(-exp(slope * (right - left))) - log(-slope)
+}
+
+.ars_build_hull <- function(x, h, d, domain, tolerance) {
+  z <- .ars_intersections(x, h, d, domain, tolerance)
+  intercept <- h - d * x
+  log_mass <- vapply(seq_along(x), function(i) {
+    .ars_log_integral_linear(intercept[i], d[i], z[i], z[i + 1L])
+  }, numeric(1L))
+  if (any(!is.finite(log_mass))) .ars_stop("The adaptive envelope has non-finite mass.")
+  list(x = x, h = h, d = d, intercept = intercept, z = z, log_mass = log_mass)
+}
+
+.ars_sample_from_piece <- function(intercept, slope, left, right) {
+  u <- runif(1L)
+  if (is.infinite(left)) return(right + log(u) / slope)
+  if (is.infinite(right)) return(left + log(u) / slope)
+  if (abs(slope) < 1e-12) return(left + u * (right - left))
+  if (slope > 0) {
+    return(right + log1p(-u * (1 - exp(slope * (left - right)))) / slope)
+  }
+  left + log1p(-u * (1 - exp(slope * (right - left)))) / slope
+}
+
+.ars_propose <- function(hull) {
+  shifted_mass <- exp(hull$log_mass - max(hull$log_mass))
+  piece <- which(runif(1L) <= cumsum(shifted_mass) / sum(shifted_mass))[1L]
+  point <- .ars_sample_from_piece(hull$intercept[piece], hull$d[piece], hull$z[piece], hull$z[piece + 1L])
+  list(x = point, piece = piece, upper = hull$intercept[piece] + hull$d[piece] * point)
+}
+
+.ars_lower_hull <- function(point, x, h) {
+  i <- findInterval(point, x)
+  if (i < 1L || i >= length(x)) return(-Inf)
+  h[i] + (h[i + 1L] - h[i]) * (point - x[i]) / (x[i + 1L] - x[i])
+}
+
+.ars_insert_point <- function(point, h_point, x, h, d, density_function, log_density, domain, tolerance) {
+  if (any(abs(x - point) <= 10 * .Machine$double.eps * pmax(1, abs(point)))) {
+    return(list(x = x, h = h, d = d))
+  }
+  position <- findInterval(point, x) + 1L
+  derivative <- .ars_derivative(point, density_function, log_density, domain)
+  new_x <- append(x, point, after = position - 1L)
+  new_h <- append(h, h_point, after = position - 1L)
+  new_d <- append(d, derivative, after = position - 1L)
+  .ars_check_log_concavity(new_x, new_h, new_d, tolerance)
+  list(x = new_x, h = new_h, d = new_d)
+}
+
+#' Draw samples using adaptive rejection sampling.
+#'
+#' @param n Number of samples to return (a non-negative integer).
+#' @param density A vectorised density function, or an expression involving x.
+#' @param domain Numeric lower and upper support limits; infinite endpoints are allowed.
+#' @param initial_points At least three distinct, interior starting points.  If NULL,
+#'   conservative points based on domain are used.
+#' @param log_density If TRUE, density returns log density values.
+#' @param max_iter Maximum proposal attempts before an error is raised.
+#' @return A numeric vector of n independent draws, with diagnostic attributes.
+ars <- function(n, density, domain = c(-Inf, Inf), initial_points = NULL,
+                log_density = FALSE, max_iter = 100000L, concavity_tol = 1e-6) {
+  calling_environment <- parent.frame()
+  .ars_validate_arguments(n, density, domain, initial_points, log_density, max_iter, concavity_tol)
+  if (n == 0L) return(numeric(0L))
+  density_function <- .ars_as_function(density, calling_environment)
+  x <- sort(unique(if (is.null(initial_points)) .ars_default_points(domain) else initial_points))
+  if (length(x) < 3L) .ars_stop("initial_points must contain at least three distinct points.")
+  if (any(x <= domain[1L]) || any(x >= domain[2L])) {
+    .ars_stop("initial_points must lie strictly inside domain.")
+  }
+  h <- .ars_log_density(x, density_function, log_density)
+  if (any(!is.finite(h))) {
+    .ars_stop("density must be positive and finite at all initial_points; provide better initial_points.")
+  }
+  d <- vapply(x, .ars_derivative, numeric(1L), density_function = density_function,
+              log_density = log_density, domain = domain)
+  .ars_check_log_concavity(x, h, d, concavity_tol)
+
+  # Test each initial chord at three locations.  For a concave log density, its
+  # graph must be no lower than every chord between hull points.
+  for (i in seq_len(length(x) - 1L)) {
+    fractions <- c(0.25, 0.5, 0.75)
+    probe <- x[i] + fractions * (x[i + 1L] - x[i])
+    probe_h <- .ars_log_density(probe, density_function, log_density)
+    chord_h <- h[i] + fractions * (h[i + 1L] - h[i])
+    if (any(!is.finite(probe_h)) || any(probe_h + concavity_tol * pmax(1, abs(chord_h)) < chord_h)) {
+      .ars_stop("The log density is not concave between initial hull points.")
+    }
+  }
+
+  hull <- .ars_build_hull(x, h, d, domain, concavity_tol)
+  samples <- numeric(n)
+  accepted <- 0L
+  attempts <- 0L
+  evaluations <- 0L
+
+  while (accepted < n) {
+    attempts <- attempts + 1L
+    if (attempts > max_iter) .ars_stop("max_iter reached before all samples were accepted.")
+    proposal <- .ars_propose(hull)
+    lower <- .ars_lower_hull(proposal$x, hull$x, hull$h)
+    log_u <- proposal$upper + log(runif(1L))
+
+    if (log_u <= lower) {
+      accepted <- accepted + 1L
+      samples[accepted] <- proposal$x
+      next
+    }
+
+    h_proposal <- .ars_log_density(proposal$x, density_function, log_density)
+    evaluations <- evaluations + 1L
+    if (!is.finite(h_proposal)) {
+      .ars_stop("Density was not positive and finite at an interior proposal; check domain and log-concavity.")
+    }
+    # A concave log density must be below its tangent envelope.  This ongoing
+    # check detects violations that were not present at the starting points.
+    if (h_proposal > proposal$upper + concavity_tol * max(1, abs(proposal$upper))) {
+      .ars_stop("The log density is not concave: it exceeded the tangent envelope during sampling.")
+    }
+    updated <- .ars_insert_point(proposal$x, h_proposal, hull$x, hull$h, hull$d,
+                                 density_function, log_density, domain, concavity_tol)
+    hull <- .ars_build_hull(updated$x, updated$h, updated$d, domain, concavity_tol)
+    if (log_u <= h_proposal) {
+      accepted <- accepted + 1L
+      samples[accepted] <- proposal$x
+    }
+  }
+
+  attr(samples, "attempts") <- attempts
+  attr(samples, "density_evaluations") <- evaluations
+  attr(samples, "hull_points") <- length(hull$x)
+  class(samples) <- c("ars_samples", class(samples))
+  samples
+}
+
+.ars_report_test <- function(name, passed, values = numeric(0L)) {
+  sample_mean <- if (length(values)) mean(values) else NA_real_
+  sample_sd <- if (length(values) > 1L) sd(values) else NA_real_
+  status <- if (isTRUE(passed)) "PASS" else "FAIL"
+  cat(sprintf("%s: %s mean=%s sd=%s\n", name, status,
+              formatC(sample_mean, digits = 5, format = "f"),
+              formatC(sample_sd, digits = 5, format = "f")))
+  isTRUE(passed)
+}
+
+#' Run formal, reproducible checks of the sampler and its key numerical module.
+#'
+#' The tests compare empirical moments and probabilities to their known values,
+#' verify input/non-concavity errors, and save normal draws to normal_samples.txt.
+test <- function() {
+  set.seed(20260813L)
+  results <- logical()
+
+  normal_draws <- ars(5000L, dnorm, initial_points = c(-2, 0, 2))
+  normal_ok <- abs(mean(normal_draws)) < 0.08 && abs(sd(normal_draws) - 1) < 0.08 &&
+    abs(mean(abs(normal_draws) <= 1) - (pnorm(1) - pnorm(-1))) < 0.035
+  results["NORMAL_SAMPLING"] <- .ars_report_test("NORMAL_SAMPLING", normal_ok, normal_draws)
+  write.table(normal_draws, file = "/app/normal_samples.txt", row.names = FALSE,
+              col.names = "sample", quote = FALSE)
+
+  exponential_draws <- ars(5000L, dexp, domain = c(0, Inf), initial_points = c(0.1, 1, 3))
+  exponential_ok <- all(exponential_draws >= 0) && abs(mean(exponential_draws) - 1) < 0.08 &&
+    abs(sd(exponential_draws) - 1) < 0.08 && abs(mean(exponential_draws <= 1) - pexp(1)) < 0.035
+  results["EXPONENTIAL_SAMPLING"] <- .ars_report_test("EXPONENTIAL_SAMPLING", exponential_ok, exponential_draws)
+
+  known_log_integral <- log(integrate(function(z) exp(0.3 + 0.7 * z), -1, 2)$value)
+  module_log_integral <- .ars_log_integral_linear(0.3, 0.7, -1, 2)
+  module_ok <- isTRUE(all.equal(module_log_integral, known_log_integral, tolerance = 1e-10))
+  results["ENVELOPE_INTEGRAL"] <- .ars_report_test("ENVELOPE_INTEGRAL", module_ok, exp(module_log_integral))
+
+  invalid_n <- inherits(try(ars(-1L, dnorm), silent = TRUE), "try-error")
+  invalid_domain <- inherits(try(ars(10L, dnorm, domain = c(1, 1)), silent = TRUE), "try-error")
+  nonvectorised <- inherits(try(ars(10L, function(x) 1, domain = c(-1, 1)), silent = TRUE), "try-error")
+  input_ok <- invalid_n && invalid_domain && nonvectorised
+  results["INPUT_VALIDATION"] <- .ars_report_test("INPUT_VALIDATION", input_ok)
+
+  bimodal_density <- function(x) exp(-(x^2 - 1)^2)
+  nonconcave_ok <- inherits(try(ars(50L, bimodal_density, initial_points = c(-2, 0, 2)), silent = TRUE), "try-error")
+  results["NON_LOG_CONCAVE"] <- .ars_report_test("NON_LOG_CONCAVE", nonconcave_ok)
+
+  invisible(results)
+}
*** End Patch";
const r = await tools.apply_patch(patch);
text(typeof r === "string" ? r : JSON.stringify(r));

